contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes an amount to send when calling play()
    function run(uint amount) public payable {
        // ensure the test contract has enough balance to send 'amount' to c
        require(address(this).balance >= amount);

        // read observable before-values
        address bankAddr = c.bank();
        uint potBefore = c.pot();
        uint cBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;

        bool reverted;
        // call play with the provided amount
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable after-values
        uint potAfter = c.pot();
        uint cBalanceAfter = address(c).balance;
        uint selfBalanceAfter = address(this).balance;

        // Constants as observable via the contract's behavior: we know them from the interface
        // but cannot access TICKET_AMOUNT/FEE_AMOUNT directly. Instead we express rules in terms of amount and balances.

        // General rule:
        // - If call reverted then amount != 10 (caller must send exactly ticket price).
        // - If call did not revert and amount == 10 then either pot increased by amount (no payout), or pot reset to 0 and contract balance decreased by FEE (1) while caller or bank received payout; we capture that the pot is either potBefore + amount or 0.
        // We express fee observation as: when pot becomes 0, c's balance after is <= cBalanceBefore + amount (it must have transferred out some funds), while when pot increases, cBalanceAfter == cBalanceBefore + amount.

        assert(
            // if reverted -> amount must not equal the ticket price (10)
            (reverted && amount != 10)
            ||
            // if not reverted -> amount must equal 10
            (!reverted && amount == 10 && (
                // either pot increased by exactly amount (no payout occurred)
                (potAfter == potBefore + amount && cBalanceAfter == cBalanceBefore + amount)
                ||
                // or pot was reset to 0 (payout branch). In that case potAfter == 0 and potBefore + amount == (some value >= amount)
                // and contract balance did not increase by the full amount (some was transferred out as payout/fee)
                (potAfter == 0 && cBalanceAfter <= cBalanceBefore + amount)
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept an input amount to forward to c.play()
    function run(uint amount) public payable {
        // ensure we have enough ETH to forward if needed
        require(address(this).balance >= amount);

        // observe initial public values
        address bank_before = c.bank();
        uint pot_before = c.pot();
        uint contract_balance_before = address(c).balance;

        // perform the state-changing call and record whether it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe final public values
        address bank_after = c.bank();
        uint pot_after = c.pot();
        uint contract_balance_after = address(c).balance;

        // General rule:
        // 1) The bank public address must never change as a result of play()
        // 2) If the call did not revert, the pot increases by at most amount (never grows by more than the ticket sent)
        //    and the change in contract balance is consistent with the pot change (no unexpected extra creation of value).
        assert(
            bank_before == bank_after
            && (
                reverted
                || (
                    // if not reverted: pot_after - pot_before <= amount
                    pot_after >= pot_before && pot_after - pot_before <= amount
                    // and change in contract balance equals pot change (since only pot and transfers change c.balance)
                    && contract_balance_after + 0 == contract_balance_before + (pot_after - pot_before)
                )
            )
        );
    }

    // accept ETH when contract pays out
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes an input amount to send as the ticket
    function run(uint amount) public payable {
        // we only consider attempts to call play with some provided amount
        require(address(this).balance >= amount, "insufficient balance to forward");

        // observe before-values
        uint pot_before = c.pot();
        uint balance_before = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint pot_after = c.pot();
        uint balance_after = address(c).balance;

        // General conservation rule: if the call did not revert, then the combined
        // total of pot + contract balance increases exactly by the forwarded amount.
        // If it reverted, no state change should be assumed; require nothing in that case.
        assert(reverted || (pot_after + balance_after == pot_before + balance_before + amount));
    }

    // allow receiving refunds when play sends Ether back
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: attempt to call play forwarding `amount` wei
    function run(uint amount) public payable {
        // need funds to forward
        require(address(this).balance >= amount);

        // only consider the canonical ticket amount for this property
        require(amount == c.TICKET_AMOUNT());

        // observe before-values
        uint pot_before = c.pot();
        uint balance_before = address(c).balance;

        // perform the call and record whether it reverted
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint pot_after = c.pot();
        uint balance_after = address(c).balance;

        // General rule:
        // If the call did not revert, then exactly one of two situations holds:
        // 1) loss branch: pot increased by amount and contract balance increased by amount
        //    (i.e., pot_after == pot_before + amount)
        // 2) win branch: pot reset to 0 and contract's on-chain balance decreased by FEE_AMOUNT
        //    (i.e., pot_after == 0 and balance_before == balance_after + c.FEE_AMOUNT())
        // The assertion encodes that either (1) or (2) holds whenever the call succeeded.
        assert(reverted || (
            (pot_after == pot_before + amount && balance_after == balance_before + amount)
            ||
            (pot_after == 0 && balance_before == balance_after + c.FEE_AMOUNT())
        ));
    }

    // accept refunds/transfers from c when play pays out
    receive() external payable { }
}

