contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call play with an amount; the rule will relate address(c).balance and c.pot() after the call.
    function run(uint amount) public payable {
        // ensure this contract has enough balance to forward 'amount'
        require(address(this).balance >= amount);

        // read before values
        uint beforePot = c.pot();
        uint beforeCBal = address(c).balance;
        uint beforeThis = address(this).balance;
        address bankAddr = c.bank();
        uint beforeBankBal = bankAddr.balance;

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after values
        uint afterPot = c.pot();
        uint afterCBal = address(c).balance;
        uint afterThis = address(this).balance;
        uint afterBankBal = bankAddr.balance;

        // General invariant to hold for all inputs: If the call reverted then nothing changed;
        // otherwise the total Ether is conserved: the sum of balances of c, bank, and this equals
        // the sum before plus amount. We express this without using literals from C, using only
        // observable balances and pot. This ensures play() does not destroy Ether.
        if (reverted) {
            assert(address(c).balance == beforeCBal && c.pot() == beforePot && address(this).balance == beforeThis && bankAddr.balance == beforeBankBal);
        } else {
            // total bal before among the three accounts
            uint totalBefore = beforeCBal + beforeBankBal + beforeThis;
            uint totalAfter = afterCBal + afterBankBal + afterThis;
            assert(totalAfter == totalBefore);
        }
    }

    // enable receiving refunds from C.play
    receive() external payable {}
}

